import collections
def comps(grid,val):
    seen=set(); out=[]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c]==val and (r,c) not in seen:
                st=[(r,c)];seen.add((r,c));cells=[]
                while st:
                    x,y=st.pop();cells.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<len(grid) and 0<=b<len(grid[0]) and grid[a][b]==val and (a,b) not in seen:
                            seen.add((a,b));st.append((a,b))
                out.append(cells)
    return out
