G=load(); print(sorted(G))
def analyze(n):
    I=G[f'Demo pair {n} input']; O=G[f'Demo pair {n} output']
    h=len(I)//2; w=len(I[0])//2
    Q={'TL':lambda r,c:I[r][c],'TR':lambda r,c:I[r][c+w],'BL':lambda r,c:I[r+h][c],'BR':lambda r,c:I[r+h][c+w]}
    # dominant per quadrant overall
    doms={nq:collections.Counter(Q[nq](r,c) for r in range(h) for c in range(w)).most_common(1)[0][0] for nq in Q}
    res=[]
    for r in range(h):
        for c in range(w):
            vals=tuple(Q[nq](r,c) for nq in ['TL','TR','BL','BR'])
            res.append((vals,O[r][c]))
    return res,doms
for n in [1,2,3,4]:
    res,doms=analyze(n)
    cc=collections.Counter((tuple(x[0]),x[1]) for x in res)
    print('demo',n,'quad dominants',doms)
    # consistency of output given multiset of values
    agg=collections.defaultdict(set)
    for vals,o in [(x[0],x[1]) for x in res]:
        agg[tuple(sorted(vals))].add(o)
    ambiguous={k:v for k,v in agg.items() if len(v)>1}
    print(' distinct multisets:',len(agg),'ambiguous:',len(ambiguous), list(ambiguous.items())[:6])

